(()=>{for(const [id,sid] of [['proposal_massing','svetlik-2022-brief'],['proposal_2021','svetlik-2021-school']]){const layer=JZM_MAP_DATA.layers.find(l=>l.id===id),p=JZM_STUDY_MODELS.scenarios[sid];if(layer){layer.geojson=p.buildings;layer.description+=' Jednotný model: omezené úpravy obrysů dle zdroje; NP zachována.';}const prov=window.JZM_LAYER_WORKSPACE?.provenance[id];if(prov){prov.short+=' · modelový převod 16. 11.';prov.steps.push('Obrysy sjednoceny podle modelového profilu; původní geometrie zachována. S003: opravena dvě zdvojení společných hran; NP nepřepisována.');prov.limits+=' Funkce a neznámé výšky zůstávají oddělenými předpoklady.';}}})();
